"""CodeBench (iOS): default bpy UX — tqdm render progress + interactive preview.

Loaded automatically at Blender startup. Installs handlers so that, with NO user
code:

  * every render shows a **tqdm progress bar** — Blender fires `render_init` /
    `render_stats` / `render_complete` synchronously on the calling thread
    *during* the (blocking) render, so a handler can drive tqdm live; and
  * every render — and every saved ``.blend`` — opens the **interactive WebGL
    viewer** in CodeBench's preview (orbit / pinch-zoom / pan, plus a
    "Rendered ⟷ 3D" toggle to the photoreal image when a render exists).

`bpy.ops.render.render()` shows a progress bar then an orbitable result, and
`bpy.ops.wm.save_as_mainfile(...)` shows the scene interactively. Generator lives
in ``codebench_blend_view``. Failures are swallowed (e.g. outside CodeBench).

The bar is a single INDETERMINATE tqdm (Cycles gives no clean per-sample count
headless, and a frame total is wrong for a still); it pulses on each render
stats update so you can see the render is alive. IMPORTANT: never evaluate a
tqdm object's truthiness — `bool(tqdm(total=None))` raises — always `is not None`.

GPU note: Cycles' Metal device works on iOS, but the FIRST render of a session
compiles Metal kernels serially (~3 min) with no Blender callback, so the bar
won't move until sampling starts; kernels cache after that.
"""

import bpy
import os
import sys
import tempfile
import time

from bpy.app.handlers import persistent

try:
    from tqdm import tqdm as _TQDM
except Exception:
    _TQDM = None

_state = {"t0": None, "bar": None}
# Timestamp of the last render-driven preview, so a save right after a render
# doesn't replace the (photoreal) render preview with a geometry-only one.
_last_preview_t = [0.0]


def _close_bar():
    b = _state.get("bar")
    if b is not None:
        try:
            b.close()
        except Exception:
            pass
        _state["bar"] = None


# ── tqdm render progress (single indeterminate bar) ────────────────────────

@persistent
def _render_init(*_args):
    _state["t0"] = time.time()
    print("[bpy] rendering… (first GPU render compiles Metal kernels ~3 min, then cached)",
          flush=True)
    if _TQDM is not None:
        try:
            _state["bar"] = _TQDM(desc="Cycles render", unit="upd", file=sys.stdout,
                                  dynamic_ncols=True, mininterval=0.5)
        except Exception:
            _state["bar"] = None


@persistent
def _render_stats(*_args):
    b = _state.get("bar")
    if b is not None:                       # NB: `if b:` raises on a total=None tqdm
        try:
            b.update(1)
        except Exception:
            pass


@persistent
def _render_cancel(*_args):
    _close_bar()


# ── interactive preview ───────────────────────────────────────────────────

def _emit_interactive(render_png):
    """Build the interactive viewer for scene 0 and ship it; embed `render_png`
    behind the Rendered toggle if given. Uses bpy.data (context is restricted in
    handlers)."""
    try:
        scene = bpy.data.scenes[0] if bpy.data.scenes else None
        if scene is None:
            return
        import codebench_blend_view as cbv
        name = os.path.basename(bpy.data.filepath) or "scene.blend"
        html = cbv.build_view(scene, render_png_path=render_png, title=name)
        if html:
            cbv.emit(html)
            _last_preview_t[0] = time.time()
            print("✓ Blender: interactive 3D preview (drag to orbit · pinch to zoom)", flush=True)
    except Exception as ex:
        sys.stderr.write("[codebench_blend_preview] interactive preview failed: %r\n" % ex)


@persistent
def _render_complete(*_args):
    _close_bar()
    if _state.get("t0"):
        print("[bpy] render done in %.1fs" % (time.time() - _state["t0"]), flush=True)
    # Save the render result so it can sit behind the "Rendered" toggle.
    png = None
    try:
        img = bpy.data.images.get("Render Result")
        if img is not None:
            png = os.path.join(tempfile.gettempdir(), "cb_render_%d.png" % int(time.time() * 1000))
            img.save_render(png)
            if not (os.path.isfile(png) and os.path.getsize(png) > 0):
                png = None
    except Exception:
        png = None
    _emit_interactive(png)


@persistent
def _save_post(*_args):
    # If a render in the last 5 s already opened a preview (with the photoreal
    # image), keep it — don't replace it with a geometry-only view.
    if time.time() - _last_preview_t[0] < 5.0:
        return
    _emit_interactive(None)


_HANDLERS = (
    ("render_init", _render_init),
    ("render_stats", _render_stats),
    ("render_complete", _render_complete),
    ("render_cancel", _render_cancel),
    ("save_post", _save_post),
)


def register():
    for name, fn in _HANDLERS:
        h = getattr(bpy.app.handlers, name, None)
        if h is not None and fn not in h:
            h.append(fn)


def unregister():
    for name, fn in _HANDLERS:
        h = getattr(bpy.app.handlers, name, None)
        if h is not None and fn in h:
            h.remove(fn)
